/*
 * Get a reference on a cell record if it is not zero.
 */
struct afs_cell *afs_try_get_cell(struct afs_cell *cell, enum afs_cell_trace reason)
{
	if (refcount_inc_not_zero(&cell->ref)) {
		trace_afs_cell(cell->debug_id, refcount_read(&cell->ref),
			       atomic_read(&cell->active), reason);
		return cell;
	}
	return NULL;
}

